package main

// Benchmarks for the latency report: go test -bench . -run ^$ ./cmd/agent-redact
// Inputs are generated by tests/bench/gen.py into $AGENT_REDACT_BENCH_DIR.

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"github.com/bl0omz/agent-redact/internal/redact"
)

func benchInput(b *testing.B, name string) string {
	dir := os.Getenv("AGENT_REDACT_BENCH_DIR")
	if dir == "" {
		b.Skip("AGENT_REDACT_BENCH_DIR not set")
	}
	data, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		b.Skip(err)
	}
	return string(data)
}

var benchSizes = []int{10240, 102400, 1048576}

func BenchmarkMask(b *testing.B) {
	for _, kind := range []string{"dirty", "clean"} {
		for _, n := range benchSizes {
			s := benchInput(b, fmt.Sprintf("%s_%d.txt", kind, n))
			for _, zh := range []bool{false, true} {
				o := defaultConfig().Options()
				if zh {
					o.Model = noModel
				}
				b.Run(fmt.Sprintf("%s/%dB/zh=%v", kind, n, zh), func(b *testing.B) {
					b.SetBytes(int64(len(s)))
					for i := 0; i < b.N; i++ {
						redact.Mask(s, o)
					}
				})
			}
		}
	}
}

func BenchmarkMaskJSON(b *testing.B) {
	for _, n := range benchSizes {
		s := benchInput(b, fmt.Sprintf("dirty_%d.txt", n))
		body, _ := json.Marshal(map[string]any{"model": "x", "input": []any{
			map[string]any{"role": "user", "content": "hi"},
			map[string]any{"type": "function_call_output", "call_id": "c1", "output": s}}})
		o := defaultConfig().Options()
		b.Run(fmt.Sprintf("%dB", n), func(b *testing.B) {
			b.SetBytes(int64(len(body)))
			for i := 0; i < b.N; i++ {
				redact.MaskJSON(body, o)
			}
		})
	}
}
